head.script:
scwin.__checkErrLog = function() {
    var temp = WebSquare.logger.getLog();
    return temp.indexOf("cannot find <w2:header> or <w2:gBody>.[test1]") == -1;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행하여 ctrl+마우스우클릭 > 로그보기를 선택한다.
    //1. Run the sample file and select ctrl + right-click> log view.
    WebSquare.wUnit.addCommand("pause", "2000");
    //Verify 1. 로그가 정상적으로 보여진다. (이전에는 로그의 [step3]과 [step4] 사이에 gridView error : cannot find <w2:header> or <w2:gBody>.[test1] 관련 오류가 보여짐)
    //1. The log is displayed normally. (Previously, the errors related to gridview error: can not find <w2: header> or <w2: gBody>. [Test1] are shown between [step3] and [step4]
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 09-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
